INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('kunsthauswien-ausstellung-renata-poljak-more-2026','KunstHausWien Ausstellung: Renata Poljak zeigt „More“ ab 12. November','Die kroatische Künstlerin Renata Poljak eröffnet im KunstHausWien den neuen Zyklus „Aqua – Water in Motion“. Ihre Schau „More“ verbindet Familiengeschichte mit Migration – bei freiem Eintritt.','Eine neue **KunstHausWien Ausstellung** widmet sich ab 12. November 2026 dem Meer als Ort von Aufbruch, Verlust und Hoffnung. Die kroatische Künstlerin und Filmemacherin Renata Poljak zeigt im Projektraum Garage des Museums ihre Einzelschau „More“. Zu sehen ist sie bis 14. März 2027, der Eintritt ist frei. Das teilte die Stadt Wien über die Rathauskorrespondenz mit.

Mit der Schau startet zugleich ein zweijähriger Ausstellungszyklus unter dem Titel „Aqua – Water in Motion“. Konzipiert hat ihn Başak Şenova, die neue Chefkuratorin des Hauses, das zur Wien Holding gehört. Das gesamte Programm des Zyklus soll im Jänner 2027 präsentiert werden.

## Worum es in der KunstHausWien Ausstellung geht

Im Mittelpunkt steht das Meer als verbindendes Element: zwischen Inseln, zwischen Lebensgeschichten, aber auch zwischen ökologischen Krisen und dem Wunsch nach einer besseren Zukunft. Poljak verwebt dabei ihre eigene Familiengeschichte mit aktuellen Fragen von Migration und Vertreibung.

Den Auftakt bildet eine Neonarbeit mit dem Titel „more, more, more“. Das Wortspiel ist bewusst mehrdeutig: Im Kroatischen steht „more“ für das Meer, kann aber auch Last bedeuten – im Englischen heißt es schlicht „mehr“.

## Familiengeschichte zwischen Brač und Feuerland

Ausgangspunkt der Erzählung ist ein Kapitel aus der Familie der Künstlerin. Ihr Urgroßvater verließ einst die dalmatinische Insel Brač, weil eine Dürre die Lebensgrundlage zerstört hatte, und suchte in Chile Arbeit. Seine Frau wartete daheim auf seine Rückkehr – vergeblich.

Diese Geschichte greifen drei Filme auf, die in der Schau gezeigt werden:

- „Partenza“ (2016)
- „Yet Another Departure“ (2018)
- „Porvenir“ (2020), gedreht in der gleichnamigen Siedlung in Feuerland

Ergänzt werden die Filme durch vier Fotocollagen aus der Werkserie „Partenza“, an der Poljak von 2016 bis 2026 gearbeitet hat. In der Ankündigung wird die Schau in einem Satz zusammengefasst: „Alles beginnt auf einer Insel und endet auf einer anderen.“

## Wer ist Renata Poljak?

Renata Poljak stammt aus Kroatien und arbeitet mit sehr unterschiedlichen Medien – von Film und Video über Fotografie und Installation bis zu Zeichnung und Neon. Inhaltlich beschäftigt sie sich vor allem mit Erinnerung, Migration und Vertreibung sowie mit den gesellschaftlichen Folgen von Kriegen und politischen Umbrüchen, insbesondere im Raum des ehemaligen Jugoslawien.

## Termine rund um die Ausstellung

Die Eröffnung ist Teil der vienna art week 2026. Die wichtigsten Daten im Überblick:

1. **11. November 2026, 19 Uhr:** Eröffnung im KunstHausWien
2. **12. November 2026 bis 14. März 2027:** Laufzeit im Projektraum Garage
3. **27. Jänner 2027:** Jahrespressekonferenz des Hauses, bei der auch das Programm des Zyklus „Aqua“ vorgestellt wird
4. **1. März 2027:** Gespräch mit Renata Poljak, Kuratorin Başak Şenova und Branko Franceschi, dem Direktor des Nationalmuseums für Moderne Kunst in Zagreb

Öffnungszeiten und weitere Details veröffentlicht das KunstHausWien auf seiner Website. Wer im Herbst Ausstellungen in Wien plant, findet mit „More“ eine Schau, die persönliche Erinnerung und große Gegenwartsthemen zusammenführt – und das ohne Eintrittskosten.','kultur','Ausstellungen','wien','news','Presseinfo Redaktion','/assets/img/artikel/kunsthauswien-ausstellung-renata-poljak-more-2026.webp','Stadt Wien – Rathauskorrespondenz','https://presse.wien.gv.at/presse/2026/10/21/more-im-kunsthauswien','published','2026-10-23T19:45:00.000Z','2026-10-23T19:44:30.694Z','KunstHausWien Ausstellung: Renata Poljak „More“','KunstHausWien Ausstellung „More“: Renata Poljak erzählt ab 12. November von Meer, Migration und Abschied. Eintritt frei – alle Termine im Überblick.','KunstHausWien Ausstellung','["KunstHausWien Ausstellung","Renata Poljak","KunstHausWien More","Ausstellung Wien November 2026","vienna art week 2026","Aqua Water in Motion","Ausstellung Migration Meer Wien","Ausstellung Wien Eintritt frei"]','KunstHausWien Ausstellung: Neonarbeit und Meer-Projektion in einem Ausstellungsraum','Dim gallery room in a converted garage space of a Viennese museum, a glowing blue neon light sculpture on a raw concrete wall, video projection of a calm Adriatic sea horizon on the opposite wall, a few visitors seen from behind at a distance, moody atmosphere','[{"q":"Wann ist die Ausstellung „More“ im KunstHausWien zu sehen?","a":"Von 12. November 2026 bis 14. März 2027 im Projektraum Garage. Eröffnet wird am 11. November um 19 Uhr."},{"q":"Kostet der Besuch Eintritt?","a":"Nein, laut Stadt Wien ist der Eintritt zur Ausstellung frei."},{"q":"Was ist „Aqua – Water in Motion“?","a":"Ein zweijähriger Ausstellungszyklus der neuen Chefkuratorin Başak Şenova, den Poljaks Schau eröffnet. Das Gesamtprogramm folgt im Jänner 2027."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=exc